// ESP32 — Buzzer Melodie
// "Alle meine Entchen" / "Twinkle Twinkle"

#define BUZZER_PIN 25
#define LEDC_CHANNEL 0
#define LEDC_RESOLUTION 8

// Frequenzen in Hz
#define C4 262
#define D4 294
#define E4 330
#define F4 349
#define G4 392
#define A4 440

// { Frequenz in Hz, Dauer in ms }
struct Note {
  int freq;
  int duration;
};

// Alle meine Entchen (erste 8 Noten)
Note melody[] = {
  {C4, 400},
  {D4, 400},
  {E4, 400},
  {F4, 400},
  {G4, 800},
  {G4, 800},
  {A4, 400},
  {A4, 400}
};

int noteCount = sizeof(melody) / sizeof(melody[0]);

void playNote(int freq, int ms) {
  ledcWriteTone(LEDC_CHANNEL, freq);
  delay(ms);
  ledcWriteTone(LEDC_CHANNEL, 0); // Pause zwischen Noten
  delay(50);
}

void setup() {
  ledcSetup(LEDC_CHANNEL, 1000, LEDC_RESOLUTION);
  ledcAttachPin(BUZZER_PIN, LEDC_CHANNEL);
}

void loop() {
  for (int i = 0; i < noteCount; i++) {
    playNote(melody[i].freq, melody[i].duration);
  }
  delay(2000); // Pause vor Wiederholung
}
